<?php namespace App\Support; final class Jwt {private static function b($v){return rtrim(strtr(base64_encode($v),'+/','-_'),'=');}public static function issue($id){$n=time();$h=self::b(json_encode(['typ'=>'JWT','alg'=>'HS256']));$p=self::b(json_encode(['user_id'=>$id,'type'=>'refresh','iat'=>$n,'exp'=>$n+86400*config('services.jwt.days')]));return "$h.$p.".self::b(hash_hmac('sha256',"$h.$p",config('services.jwt.secret'),true));}public static function read($t){$x=explode('.',$t);if(count($x)!==3)return null;[$h,$p,$s]=$x;$d=json_decode(base64_decode(strtr($p,'-_','+/')),true);$e=self::b(hash_hmac('sha256',"$h.$p",config('services.jwt.secret'),true));return hash_equals($e,$s)&&($d['exp']??0)>=time()?$d:null;}}
